// TypeScript example: adaptive invoker consumer
import { AdaptiveInvoker, StreamEvent } from 'redwood-sdk';

async function run() {
  const inv = new AdaptiveInvoker({ apiKey: process.env.RW_KEY });
  const stream = inv.invokeStreaming({ model: 'rw-textrun-1', prompt: 'Summarize the doc and call summarizer tool if needed' });

  for await (const ev of stream) {
    if (ev.type === 'token') {
      process.stdout.write(ev.payload.text);
    } else if (ev.type === 'tool_request') {
      // call external tool inline and return result by callId
      const { callId, toolName, args } = ev.payload;
      const result = await runTool(toolName, args);
      await inv.sendToolResult(callId, result);
    } else if (ev.type === 'structured') {
      // validated structured JSON per schema
      console.log('
[STRUCTURED OUTPUT]', JSON.stringify(ev.payload, null, 2));
    } else if (ev.type === 'checkpoint') {
      // persist checkpoint.id for resumability
      await saveCheckpoint(ev.payload.checkpointId);
    }
  }
}

async function runTool(name: string, args: any) {
  if (name === 'summarizer') return { summary: '...computed summary...' };
  return { error: 'unknown tool' };
}

run().catch(console.error);

