// Go example: adaptive invoker consumer
package main

import (
  "context"
  "fmt"
  "time"

  rw "github.com/redwood/rw-sdk-go"
)

func main() {
  ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
  defer cancel()

  client := rw.NewInvoker("${RW_KEY}")
  ch, err := client.InvokeStreaming(ctx, rw.InvokeOptions{Model: "rw-textrun-1", Prompt: "Generate and call tools"})
  if err != nil {
    panic(err)
  }
  for ev := range ch {
    switch ev.Type {
    case rw.EventToken:
      fmt.Print(ev.Payload.(map[string]interface{})["text"])
    case rw.EventToolRequest:
      payload := ev.Payload.(map[string]interface{})
      callId := payload["call_id"].(string)
      tool := payload["tool"].(string)
      // synchronous tool execution
      result := callTool(tool, payload["args"])
      client.SendToolResult(ctx, callId, result)
    case rw.EventStructured:
      fmt.Printf("\nSTRUCTURED: %#v\n", ev.Payload)
    case rw.EventCheckpoint:
      // save checkpoint id for resumption
      saveCheckpoint(payload["id"].(string))
    }
  }
}

func callTool(name string, args interface{}) interface{} {
  if name == "summarizer" {
    return map[string]string{"summary": "computed summary"}
  }
  return map[string]string{"error": "unknown tool"}
}
